//! Cargo-driven `rpcrt4.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x7bb10000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ffaa000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ffaa000000u64)),
        o => panic!("rpcrt4-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:c:wine_dll_register", "engine:uuid", "engine:pseh", "engine:oldnames", "import:iphlpapi", "import:wininet", "import:secur32", "import:user32", "import:ole32", "import:oleaut32", "import:advapi32", "import:advapi32_vista", "import:kernel32_vista", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust", "body"],
        "x86_64" => &["engine:wine", "engine:c:wine_dll_register", "engine:uuid", "engine:pseh", "engine:oldnames", "import:iphlpapi", "import:wininet", "import:secur32", "import:user32", "import:ole32", "import:oleaut32", "import:advapi32", "import:advapi32_vista", "import:kernel32_vista", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body"],
        "aarch64" => &["engine:wine", "engine:c:wine_dll_register", "engine:uuid", "engine:pseh", "engine:oldnames", "import:iphlpapi", "import:wininet", "import:secur32", "import:user32", "import:ole32", "import:oleaut32", "import:advapi32", "import:advapi32_vista", "import:kernel32_vista", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/rpcrt4",
        "dll/win32/rpcrt4",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "COM_NO_WINDOWS_H",
        "MSWMSG",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_CRT_NON_CONFORMING_SWPRINTFS",
        "_DLL",
        "_RPCRT4_",
        "_WIN32_WINNT=0x600",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("rpcrt4_shims", &["dll/win32/rpcrt4/cproxy.c", "dll/win32/rpcrt4/cpsf.c", "dll/win32/rpcrt4/ndr_clientserver.c", "dll/win32/rpcrt4/ndr_contexthandle.c", "dll/win32/rpcrt4/ndr_es.c", "dll/win32/rpcrt4/ndr_fullpointer.c", "dll/win32/rpcrt4/ndr_marshall.c", "dll/win32/rpcrt4/ndr_ole.c", "dll/win32/rpcrt4/ros_extra.c", "dll/win32/rpcrt4/rpc_assoc.c", "dll/win32/rpcrt4/rpc_async.c", "dll/win32/rpcrt4/rpc_binding.c", "dll/win32/rpcrt4/rpc_callattr.c", "dll/win32/rpcrt4/rpc_message.c", "dll/win32/rpcrt4/rpcrt4_main.c", "dll/win32/rpcrt4/rpc_transport.c", "dll/win32/rpcrt4/thunks.c", "dll/win32/rpcrt4/unix_func.c", "dll/win32/rpcrt4/epm_c.c", "dll/win32/rpcrt4/cstub.c", "dll/win32/rpcrt4/ndr_stubless.c", "dll/win32/rpcrt4/rpc_server.c", "dll/win32/rpcrt4/rpc_epmap.c", "dll/win32/rpcrt4/epm_guard.c", "dll/win32/rpcrt4/ndr_typelib.c", "dll/win32/rpcrt4/ndr_types_p.c", "dll/win32/rpcrt4/proxy.dlldata.c"])
        .whole_c_objects("rpcrt4_shims")
        .rc("dll/win32/rpcrt4/rpcrt4.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/iphlpapi/iphlpapi.spec", "iphlpapi.dll", "iphlpapi")
        .delay_import_lib("dll/win32/wininet/wininet.spec", "wininet.dll", "wininet")
        .delay_import_lib("dll/win32/secur32/secur32.spec", "secur32.dll", "secur32")
        .delay_import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .delay_import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .delay_import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/advapi32_vista/advapi32_vista.spec", "advapi32_vista.dll", "advapi32_vista")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        // No code of its own: link nothing from rustc's bin (its panic
        // handler, i386's rsbegin/rsend), so the PE is cmake's.
        .shell_less()
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
